(() => {
 'use strict';
 const fr=document.documentElement.lang.startsWith('fr'),L=(en,frText)=>fr?frText:en,$=(s,r=document)=>r.querySelector(s),money=c=>new Intl.NumberFormat(fr?'fr-CA':'en-CA',{style:'currency',currency:'CAD'}).format(c/100),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),key=()=>crypto.randomUUID()+crypto.randomUUID();
 const state={order:null,token:null,quote:null,claimKey:key()};
 async function api(path,options={}){const response=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json','X-Lumina-Request':'1',...(state.token?{Authorization:'Bearer '+state.token}:{}),...options.headers}});const data=await response.json();if(!response.ok)throw new Error(data.error||L('Request failed','Échec de la demande'));return data;}
 const post=(path,data,headers={})=>api(path,{method:'POST',headers,body:JSON.stringify(data)});
 const orderPath=()=>'/orders/'+state.order.public_id;
 const trackingLink=()=>location.origin+(fr?'/fr':'')+'/order/#'+new URLSearchParams({id:state.order.public_id,key:state.token});
 const statusText=s=>({pending_payment:L('Pending payment','En attente de paiement'),awaiting_verification:L('Awaiting verification','En attente de vérification'),paid:L('Payment verified','Paiement vérifié'),refunded:L('Refunded','Remboursé'),processing:L('Preparing fulfillment','Préparation de l’activation'),fulfilled:L('Fulfilled','Activée'),cancelled:L('Cancelled','Annulée'),active:L('Active','Actif'),expired:L('Expired','Expiré'),issued:L('Issued','Émise'),credited:L('Credited','Créditée')})[s]||s;
 const notice=error=>{const el=$('[data-server-status]')||$('[data-commerce-status]');if(el)el.textContent=error.message||error;};
 async function downloadInvoice(id){const response=await fetch('/api'+orderPath()+'/invoices/'+id+'/pdf',{headers:{Authorization:'Bearer '+state.token}});if(!response.ok)throw new Error(L('Invoice unavailable','Facture indisponible'));const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download='Lumina-invoice-'+id+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function paymentUI(root){root.innerHTML=`<div class="commerce-box"><h3>${L('Order','Commande')} ${esc(state.order.reference)}</h3><p>${esc(state.order.plan_name)} · ${money(state.order.total_cents)} CAD</p><p>${L('Save your private tracking link. Anyone with it can view this order.','Conservez votre lien privé. Toute personne disposant de ce lien peut voir cette commande.')}</p><a class="text-link" data-no-translate href="${esc(trackingLink())}">${L('Save this tracking link','Conserver ce lien de suivi')}</a></div><form data-method-form class="commerce-box"><label class="field">${L('Payment method','Mode de paiement')}<select name="method"><option value="interac">Interac e-Transfer</option><option value="crypto">USDT / USDC</option></select></label><div class="grid-2"><label class="field">${L('Token','Jeton')}<select name="token"><option>USDT</option><option>USDC</option></select></label><label class="field">${L('Network','Réseau')}<select name="network"><option value="ethereum">Ethereum</option><option value="polygon">Polygon</option><option value="tron">Tron (USDT)</option></select></label></div><button class="btn primary">${L('Generate payment instructions','Afficher les instructions de paiement')}</button></form><div data-quote></div>`;
 $('[data-method-form]',root).addEventListener('submit',async e=>{e.preventDefault();const button=$('button',e.target);button.disabled=true;try{state.quote=await post(orderPath()+'/quote',Object.fromEntries(new FormData(e.target)));state.claimKey=key();renderQuote($('[data-quote]',root));notice('');}catch(error){notice(error);}finally{button.disabled=false;}});
 }
 function renderQuote(root){const q=state.quote,fields=q.method==='interac'?[[L('Recipient name','Destinataire'),q.instructions.recipientName],[L('Recipient email','Courriel du destinataire'),q.instructions.email],[L('Exact amount CAD','Montant exact CAD'),q.amount],[L('Transfer memo','Message du virement'),q.reference]]:[[L('Token / network','Jeton / réseau'),q.token+' / '+q.network],[L('Wallet address','Adresse du portefeuille'),q.instructions.address],[L('Exact amount','Montant exact'),q.amount+' '+q.token],[L('Order reference','Référence de commande'),q.reference]];
 root.innerHTML=`<div class="commerce-box"><h3>${q.mode==='test'?L('TEST MODE: do not send money','MODE TEST : n’envoyez aucun paiement'):L('Payment instructions','Instructions de paiement')}</h3>${fields.map(([label,value],i)=>`<div class="transfer-field"><div><span>${esc(label)}</span><strong data-no-translate>${esc(value)}</strong></div><button class="copy-field" type="button" data-copy-value="${i}">${L('Copy','Copier')}</button></div>`).join('')}${q.method==='crypto'?`<img class="payment-qr" src="${esc(q.instructions.qr)}" alt="${L('Wallet QR code','Code QR du portefeuille')}" width="240" height="240"><p>${L('Use only the exact token and network shown.','Utilisez uniquement le jeton et le réseau indiqués.')} ${esc(q.instructions.rate.source)} · 1 ${q.token} = ${q.instructions.rate.cadPerToken} CAD</p>`:''}<p>${L('Quote expires','Le devis expire')} ${new Date(q.expiresAt).toLocaleString(fr?'fr-CA':'en-CA')}</p><form data-claim-form><label class="field">${q.method==='interac'?L('Transfer confirmation number','Numéro de confirmation du virement'):L('Transaction hash','Identifiant de transaction')}<input name="confirmation" minlength="3" maxlength="200" required autocomplete="off"></label><p>${L('A claim is not proof of payment. An administrator must independently verify receipt.','Une déclaration ne confirme pas le paiement. Un administrateur doit vérifier la réception indépendamment.')}</p><button class="btn primary">${q.method==='interac'?L("I've sent the payment",'J’ai envoyé le virement'):L('Submit transaction for review','Soumettre la transaction à vérification')}</button></form></div>`;
 root.querySelectorAll('[data-copy-value]').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(fields[Number(b.dataset.copyValue)][1]);b.textContent=L('Copied','Copié');}catch{notice(L('Select and copy the field manually.','Sélectionnez et copiez le champ manuellement.'));}}));
 $('[data-claim-form]',root).addEventListener('submit',async e=>{e.preventDefault();const button=$('button',e.target);button.disabled=true;try{await post(orderPath()+'/claims',{quoteId:q.id,confirmation:new FormData(e.target).get('confirmation')},{'Idempotency-Key':state.claimKey});location.href=trackingLink();}catch(error){notice(error);button.disabled=false;}});
 }
 const checkout=$('[data-checkout]');if(checkout){const form=$('[data-order-form]',checkout),catalog=JSON.parse($('#site-catalog').textContent),all=[...catalog.plans,catalog.trial],params=new URLSearchParams(location.search);let requestKey=key(),fingerprint='';
 const wanted=all.find(p=>p.id===(params.get('plan')||params.get('p')))||all[0];$(`input[name=plan][value="${wanted.id}"]`,form).checked=true;form.elements.months.value=['1','3','6','12'].includes(params.get('months'))?params.get('months'):'12';form.elements.screens.value=['1','2','3'].includes(params.get('screens'))?params.get('screens'):'1';
 const update=()=>{const p=all.find(p=>p.id===form.elements.plan.value),trial=p.id==='trial',months=trial?0:Number(form.elements.months.value),screens=trial?1:Number(form.elements.screens.value),total=trial?p.price:p.prices[months][screens-1];form.elements.months.disabled=trial;form.elements.screens.disabled=trial;$('[data-summary-plan]',checkout).textContent=p.name;$('[data-summary-term]',checkout).textContent=trial?'24 h':months+L(' months',' mois');$('[data-summary-screens]',checkout).textContent=screens;$('[data-summary-total]',checkout).textContent=money(Math.round(total*100));$('[data-summary-equivalent]',checkout).textContent=L('Final total and applicable taxes are validated by the server.','Le total et les taxes applicables sont validés par le serveur.');};
 form.addEventListener('change',update);form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;const p=all.find(p=>p.id===form.elements.plan.value),payload={plan:p.id,months:p.id==='trial'?0:Number(form.elements.months.value),screens:p.id==='trial'?1:Number(form.elements.screens.value),name:form.elements.name.value,email:form.elements.email.value,device:form.elements.device.value,locale:fr?'fr-CA':'en-CA'},fp=JSON.stringify(payload);if(fingerprint&&fingerprint!==fp)requestKey=key();fingerprint=fp;const button=$('button[type=submit]',form);button.disabled=true;try{const result=await post('/orders',payload,{'Idempotency-Key':requestKey});state.order=result.order;state.token=result.accessToken;checkout.querySelectorAll('[data-checkout-step]').forEach(el=>el.hidden=el.dataset.checkoutStep!=='2');paymentUI($('[data-server-payment]',checkout));$('[data-summary-total]',checkout).textContent=money(state.order.total_cents);notice('');}catch(error){notice(error);}finally{button.disabled=false;}});
 $('[data-server-back]',checkout).addEventListener('click',()=>{checkout.querySelectorAll('[data-checkout-step]').forEach(el=>el.hidden=el.dataset.checkoutStep!=='1');});update();}

 async function showSubscriptionAccess(root){const button=root.querySelector('[data-view-access]');button.disabled=true;try{const access=await api(orderPath()+'/access'),details=access.details,fields=details.type==='xtream'?[[L('Server URL','URL du serveur'),details.serverUrl],[L('Username','Identifiant'),details.username],[L('Password','Mot de passe'),details.password]]:[[L('M3U playlist URL','URL de la liste M3U'),details.playlistUrl]];const area=root.querySelector('[data-access-fields]');area.innerHTML=fields.map(([label,value],i)=>`<div class="transfer-field"><div><span>${esc(label)}</span>${details.type==='xtream'&&i===2?`<input type="password" readonly data-access-password aria-label="${esc(label)}">`:details.type==='m3u'?`<input type="password" readonly data-access-password aria-label="${esc(label)}">`:`<strong>${esc(value)}</strong>`}</div><button type="button" class="copy-field" data-copy-access="${i}">${L('Copy','Copier')}</button></div>`).join('')+`<button type="button" class="btn small" data-toggle-password>${L('Show / hide secret','Afficher / masquer le secret')}</button><p>${L('Expires','Expire')} ${new Date(access.expiresAt).toLocaleString(fr?'fr-CA':'en-CA')}</p><pre>${esc(details.instructions)}</pre>`;const secret=area.querySelector('[data-access-password]');if(secret)secret.value=details.type==='xtream'?details.password:details.playlistUrl;area.querySelector('[data-toggle-password]').addEventListener('click',()=>{if(secret)secret.type=secret.type==='password'?'text':'password';});area.querySelectorAll('[data-copy-access]').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(fields[Number(b.dataset.copyAccess)][1]);b.textContent=L('Copied','Copié');}catch{notice(L('Copy the field manually.','Copiez le champ manuellement.'));}}));}catch(error){notice(error);button.disabled=false;}}
 const tracker=$('[data-order-tracker]');if(tracker){document.querySelector('.skip')?.addEventListener('click',event=>{event.preventDefault();const main=document.querySelector('main');main.tabIndex=-1;main.focus();});const load=async()=>{try{const params=new URLSearchParams(location.hash.slice(1));state.token=params.get('key');const id=params.get('id');if(!id||!state.token)return;state.order={public_id:id};const o=await api(orderPath());state.order=o;tracker.innerHTML=`<div class="commerce-box"><h2>${esc(o.reference)}</h2><p>${esc(o.plan_name)} · ${money(o.total_cents)} CAD</p><dl class="commerce-dl"><dt>${L('Payment status','État du paiement')}</dt><dd>${esc(statusText(o.payment_status))}</dd><dt>${L('Order status','État de la commande')}</dt><dd>${esc(statusText(o.order_status))}</dd></dl>${o.subscriptions.map(s=>`<p>${esc(statusText(s.effective_status))}: ${esc(s.activated_at)} / ${esc(s.expires_at)}</p>`).join('')}${o.delivery?.configured&&o.payment_status==='paid'&&o.order_status==='fulfilled'?`<section class="customer-access-fields"><h3>${L('Your IPTV subscription','Votre abonnement IPTV')}</h3><button type="button" class="btn primary" data-view-access>${L('View my IPTV access','Voir mes accès IPTV')}</button><div data-access-fields></div></section>`:''}<h3>${L('Invoices','Factures')}</h3>${o.invoices.map(i=>`<button class="btn" data-invoice="${i.id}">${esc(i.number)} · ${esc(statusText(i.status))}</button>`).join('')}<p>${L('Refresh this page to check for updates.','Actualisez la page pour vérifier les mises à jour.')}</p></div><div data-tracker-payment></div>`;tracker.querySelector('[data-view-access]')?.addEventListener('click',()=>showSubscriptionAccess(tracker));tracker.querySelectorAll('[data-invoice]').forEach(b=>b.addEventListener('click',()=>downloadInvoice(b.dataset.invoice).catch(notice)));if(o.payment_status==='pending_payment')paymentUI($('[data-tracker-payment]',tracker));}catch(error){notice(error);}};
 $('[data-track-open]').addEventListener('submit',e=>{e.preventDefault();try{const link=new URL(new FormData(e.target).get('tracking'));if(link.origin!==location.origin)throw Error(L('Use a tracking link from this site.','Utilisez un lien de ce site.'));location.hash=link.hash;}catch(error){notice(error);}});addEventListener('hashchange',load);load();}
})();
